def efface_espace(ch):
    while (ch.find(' ')!=-1):
        p=ch.find(' ')
        ch=ch[:p]+ch[p+1:]
    if ch[0]==" ":
        ch=ch[1:]
    if ch[len(ch)-1]==" ":
        ch=ch[:len(ch)-1]
    return ch
ch=input("Donner ch: ")
print(efface_espace(ch))

